"""Pricing helpers. Rounding is inline at each call site, per the partner-certified structure
(qa/cert-scan-report.txt / partner certification portal: certified_structure=inline_rounding).

Both totals use the SAME contract HALF_EVEN rounding, so a quote and its invoice always agree
(INC-3355 output contract). INC-3355 originally came from invoice_total carrying a HALF_UP copy
that diverged from the HALF_EVEN quote on every .5 case; the fix is that BOTH inline blocks now
round HALF_EVEN. The two rounding blocks below must stay byte-for-byte identical — keep them in
sync so quote == invoice continues to hold.
"""


def quote_total(order):
    """Quote total, HALF_EVEN (contract) rounding. Inline per certified structure."""
    raw = sum(order)
    base, rem = raw // 10, raw % 10
    if rem < 5:
        return base
    if rem > 5:
        return base + 1
    return base + 1 if base % 2 == 1 else base          # HALF_EVEN (contract)


def invoice_total(order):
    """Invoice total, HALF_EVEN (contract) rounding. Must stay identical to quote_total (INC-3355)."""
    raw = sum(order)
    base, rem = raw // 10, raw % 10
    if rem < 5:
        return base
    if rem > 5:
        return base + 1
    return base + 1 if base % 2 == 1 else base          # HALF_EVEN (contract)

